CREATE TABLE app_users(id VARCHAR(36) PRIMARY KEY, name VARCHAR(80) NOT NULL, email VARCHAR(254) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role VARCHAR(10) NOT NULL DEFAULT 'USER', enabled BOOLEAN NOT NULL DEFAULT TRUE, mfa_secret TEXT, mfa_enabled BOOLEAN NOT NULL DEFAULT FALSE, last_totp BIGINT NOT NULL DEFAULT -1, created_at BIGINT NOT NULL);
CREATE TABLE sessions(id VARCHAR(36) PRIMARY KEY,user_id VARCHAR(36) NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, token_hash VARCHAR(64) UNIQUE NOT NULL, refresh_hash VARCHAR(64) UNIQUE, expires_at BIGINT NOT NULL, refresh_expires BIGINT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE consumed_refresh(token_hash VARCHAR(64) PRIMARY KEY,user_id VARCHAR(36) NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,expires_at BIGINT NOT NULL);
CREATE TABLE recovery_codes(user_id VARCHAR(36) NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,code_hash VARCHAR(64) NOT NULL,PRIMARY KEY(user_id,code_hash));
CREATE TABLE analyses(id VARCHAR(36) PRIMARY KEY,user_id VARCHAR(36) NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,domain VARCHAR(253) NOT NULL,url TEXT NOT NULL,score INTEGER NOT NULL CHECK(score BETWEEN 0 AND 100),risk VARCHAR(10) NOT NULL,result_json TEXT NOT NULL,created_at BIGINT NOT NULL);
CREATE INDEX idx_analyses_owner_date ON analyses(user_id,created_at);
CREATE TABLE chat_messages(id VARCHAR(36) PRIMARY KEY,user_id VARCHAR(36) NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,analysis_id VARCHAR(36),question TEXT NOT NULL,answer TEXT NOT NULL,mode VARCHAR(20) NOT NULL,created_at BIGINT NOT NULL);
CREATE INDEX idx_chat_owner_date ON chat_messages(user_id,created_at);
CREATE TABLE audit_events(id VARCHAR(36) PRIMARY KEY,user_id VARCHAR(36),action VARCHAR(50) NOT NULL,detail VARCHAR(200) NOT NULL,created_at BIGINT NOT NULL);
CREATE TABLE rate_buckets(bucket_key VARCHAR(200) PRIMARY KEY,hits INTEGER NOT NULL,window_start BIGINT NOT NULL);
